entries[253077] = { ["name"] = "Verwundbarkeit aufdecken", ["text"] = "40 Meter Reichweite\nSofort\nDeckt Schwächen von Gegnern in der Nähe auf. Fügt Gegnern innerhalb von 8 Metern körperlichen Schaden zu und erhöht ihren erlittenen körperlichen Schaden 8 Sek. lang um 15%." }
entries[253078] = { ["name"] = "Ansturm", ["text"] = "100 Meter Reichweite\nWirken in 2 sek. 5 sek. Abklingzeit\nStürmt einen Gegner an, fügt Gegnern in einer Linie 150 körperlichen Schaden zu und betäubt sie für 2 Sek." }
entries[253079] = { ["name"] = "Grausames Spalten", ["text"] = "20 Meter Reichweite\nSofort\nFügt allen Gegnern in einem kegelförmigen Bereich vor dem Zaubernden 29 körperlichen Schaden zu." }
