entries[253084] = { ["name"] = "Verstärkte Rüstung", ["text"] = "20 Meter Reichweite\nSofort\nVerstärkt die Rüstung eines Verbündeten und verringert für 10 Min. seinen erlittenen Schaden um 10%." }
entries[253085] = { ["name"] = "Stab des frostigen Höhlenbewohners", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert den Stab in die Luft, der Gegnern innerhalb von 10 Metern 10 Sek. lang alle 1 Sek. 2 Frostschaden zufügt und ihre Bewegungsgeschwindigkeit um 30% verringert." }
