entries[253093] = { ["name"] = "Lichtinfusion", ["text"] = "Rang 1/ 3 Artefakt Boni\nCa. 4 Procs pro Minute\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, zusätzlich 101000 Heiligschaden zu verursachen. Eure Heilungszauber und -fähigkeiten haben eine Chance, um 101000 Gesundheit zu heilen.\n(1s Abklingzeit)" }
