entries[253102] = { ["name"] = "Essenz verschlingen", ["text"] = "35 Meter Reichweite\nWirken in 2 sek.\nSpringt zu einem zufälligen Gegner und fügt allen Spielercharakteren innerhalb von 5 Metern um diesen Ort 142 körperlichen Schaden zu. Der Zaubernde erhält 2-mal den verursachten Schaden als Gesundheit." }
