entries[253106] = { ["name"] = "Farbenprächtiger Manarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen farbenprächtigen Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nTeufelsgeflecktes Ei" }
entries[253107] = { ["name"] = "Glimmernder Manarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen flackernden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nGiftschwanzhimmelsflosse\nZone:\nEredath" }
entries[253108] = { ["name"] = "Teufelsschimmermanarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen Teufelsschimmermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Armee des Lichts konnte nicht alle heimischen Spezies auf Argus retten. Unzählige gingen im Chaos verloren.\"\nBeute von:\nTeufelsgeflecktes Ei" }
entries[253109] = { ["name"] = "Schillernder Manarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen schillernden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nTeufelsgeflecktes Ei" }
entries[253110] = { ["name"] = "Monelitgehärtete Hufplatten", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nMoneliterz (25), Langlebiger Fluxus (2)\nStellt monelitgehärtete Hufplatten her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (50)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n\nBenutzen: Beschlägt Euer Reittier mit Hufplatten, die Eure Geschwindigkeit beim Reiten in Kul Tiras oder Zandalar für 2 Stunden um 20% erhöhen.\n\nDie Dauer ist für Schmiede vervierfacht." }
entries[253111] = { ["name"] = "Umarmung des Lichts", ["text"] = "Rang 1/ 3 Artefakt Boni\nCa. 8 Procs pro Minute\nWenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr 'Umarmung des Lichts' erhaltet. Der Effekt stellt im Verlauf von 6 Sek. 45500 Gesundheit wieder her. 'Umarmung des Lichts' ist bis zu 5-mal stapelbar.\n(1s Abklingzeit)" }
entries[253112] = { ["name"] = "Monelitgehärtete Steigbügel", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nMoneliterz (25), Langlebiger Fluxus (2)\nStellt monelitgehärtete Steigbügel her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (50)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n\nBenutzen: Versieht Euer Reittier mit Steigbügeln, die Euch für 2 Stunden Interaktionen beim Reiten in Kul Tiras oder Zandalar ermöglichen.\n\nDie Dauer ist für Schmiede vervierfacht." }
