entries[253122] = { ["name"] = "Magnetischer Diskombobulator", ["text"] = "Wirken in 3 sek.\nReagenzien:\nMoneliterz (25), Sturmsilbererz (10)\nOptionale Reagenzien:\n[] (#47)\nStellt einen magnetischen Diskombobulator her.\nBeruf:\nIngenieurskunst (1)\n\nMagnetischer Diskombobulator\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n7 - 10 Schaden Geschwindigkeit 2.60\n(3.3 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nHaltbarkeit 75 / 75\n45\n\"Sein Magnetismus zeigt sich primär darin, dass die Schädel von Gegnern in die Bahn seiner Hiebe gezogen werden.\"" }
