entries[253145] = { ["name"] = "Khaz'gorischer Schmiedehammer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nBlut des Titanen (30), Werkzeuge zum Präzisionssegnen , Azerokks Faust , Sturmsilbererz (30), Platinerz (20), Expulsom (10)\nErschafft einen khaz'gorischen Hammer.\nQuest:\nEine Anleitung für die Ewigkeit\nZone:\nTiragardesund\n\nQuest:\nEine Anleitung für die Ewigkeit\nZone:\nZuldazar\n\nKhaz'gorischer Schmiedehammer\nWird beim Aufheben gebunden\nEinzigartigWerkzeug für Schmiedekunst\nBeim Erschaffen von Schmiederüstung oder -waffen besteht eine Chance, dass sie mit der Eigenschaft 'Unzerstörbar' belegt werden.\nBenutzen: Gestattet es dem Benutzer, einen Ausrüstungsgegenstand sofort zu reparieren. (1 Stunde Abklingzeit)\nAnlegen: +4 Schmiedekunstfertigkeit.\n50\nBenötigt Schmiedekunst von Kul Tiras\n(150)\n\"Dieser Hammer kann anstelle eines normalen Schmiedehammers für Handwerksprojekte verwendet werden.\"" }
entries[253149] = { ["name"] = "Zauberklinge des ehrenhaften Kämpfers", ["text"] = "Wirken in 2.5 sek.\nTools: Schmiedehammer\nReagenzien:\nSturmsilbererz (36), Elementarfluxus (10)\nOptionale Reagenzien:\n[] (#47)\nVerringert die erforderlichen Materialien zur Herstellung einer Zauberklinge des ehrenhaften Kämpfers.\nVerkäufer:\nOzgrom Grollzahn\nZone:\nZuldazar\nKosten:\n2\n\nAllianz\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\n50\nHorde\nZauberklinge des ehrenhaften Kämpfers\nWird beim Anlegen gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\nHaltbarkeit 65 / 65\n50" }
